import 'package:flutter/material.dart';

import '../../../core/data/app_history.dart';

class HistoryPage extends StatefulWidget { const HistoryPage({super.key}); @override State<HistoryPage> createState()=>_HistoryPageState(); }
class _HistoryPageState extends State<HistoryPage>{final _storage=AppHistoryStorage();List<HistoryEntry> _items=[];String _filter='All';@override void initState(){super.initState();_load();}Future<void> _load()async{final v=await _storage.load();if(mounted)setState(()=>_items=v);} @override Widget build(BuildContext context){final modules=['All','Time Study','Catalog','Line Balance','VSM','Downtime'];final filtered=_filter=='All'?_items:_items.where((e)=>e.module==_filter).toList();return Scaffold(appBar:AppBar(title:const Text('Global History')),body:Column(children:[SingleChildScrollView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.all(12),child:Row(children:modules.map((m)=>Padding(padding:const EdgeInsets.only(right:8),child:ChoiceChip(label:Text(m),selected:_filter==m,onSelected:(_)=>setState(()=>_filter=m)))).toList())),Expanded(child:filtered.isEmpty?const Center(child:Text('History hozircha bo‘sh')):ListView.builder(itemCount:filtered.length,itemBuilder:(_,i){final e=filtered[i];return ListTile(leading:CircleAvatar(child:Text(e.module.substring(0,1))),title:Text(e.title),subtitle:Text('${e.module} • ${e.subtitle}'),trailing:Text('${e.savedAt.year}-${e.savedAt.month.toString().padLeft(2,'0')}-${e.savedAt.day.toString().padLeft(2,'0')}');})))]));}}
